CREATE TABLE `agg_week_results` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key.',
  `series_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.series, indicating the series for which this week''s statistics apply.',
  `season_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.seasons, indicating the season for which this week''s statistics apply.',
  `week_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.weeks, indicating the week for which this week''s statistics apply.',
  `track_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.tracks, indicating the track for which this week''s statistics apply.',
  `race_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.races, indicating the race for which this week''s statistics apply.',
  `car_driver_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.car_drivers, indicating the car/driver combination for which this week''s statistics apply.',
  `car_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.cars, indicating the car for which this week''s statistics apply.',
  `manufacturer_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.manufacturers, indicating the manufacturer for which this week''s statistics apply.',
  `car_generation_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.car_generations, indicating the generation for this week''s statistics.',
  `car_generation_model_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.car_generation_models, indicating the generation model for this week''s statistics.',
  `team_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Foreign key to nascar.teams, indicating the team for which this week''s statistics apply.',
  `driver_id` bigint(20) unsigned NOT NULL COMMENT 'Foreign key to nascar.drivers, indicating the driver for which this week''s statistics apply.',
  `r_start_position` int(10) unsigned DEFAULT NULL COMMENT 'Race starting position',
  `r_finish_position` int(10) unsigned DEFAULT NULL COMMENT 'Race finishing position',
  `r_place_diff` int(11) DEFAULT NULL COMMENT 'Race place differential',
  `r_best_position` int(10) unsigned DEFAULT NULL COMMENT 'Race best position',
  `r_worst_position` int(10) unsigned DEFAULT NULL COMMENT 'Race worst position',
  `r_average_position` int(10) unsigned DEFAULT NULL COMMENT 'Race average position',
  `r_green_flag_passes` int(10) unsigned DEFAULT NULL COMMENT 'Race green flag passes',
  `r_green_flag_times_passed` int(10) unsigned DEFAULT NULL COMMENT 'Race green flag times passed',
  `r_green_flag_pass_diff` int(11) DEFAULT NULL COMMENT 'Race green flag pass difference',
  `r_quality_passes` int(10) unsigned DEFAULT NULL COMMENT 'Race quality passes',
  `r_quality_passes_pct` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Race quality passes percentage',
  `r_total_fastest_laps` int(10) unsigned DEFAULT NULL COMMENT 'Race total fastest laps',
  `r_total_fastest_laps_pct` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Race total fastest laps percentage',
  `r_total_top_15_laps` int(10) unsigned DEFAULT NULL COMMENT 'Race total top 15 laps',
  `r_total_top_15_laps_pct` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Race total top 15 laps percentage',
  `r_total_laps_led` int(10) unsigned DEFAULT NULL COMMENT 'Race total laps led',
  `r_total_laps_led_pct` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Race total laps led percentage',
  `r_total_laps_completed` int(10) unsigned DEFAULT NULL COMMENT 'Race total laps completed',
  `r_total_laps_completed_pct` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Race total laps completed percentage',
  `r_driver_rating` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Race driver rating',
  `r_car_status` varchar(255) DEFAULT NULL COMMENT 'Race car status',
  `r_avg_pitstop_crew_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average pit stop crew time',
  `r_avg_pitstop_driver_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average pit stop driver time',
  `r_total_pitstops` int(10) unsigned DEFAULT NULL COMMENT 'Race total pit stops',
  `r_avg_4_pitstop_crew_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average 4-wheel pit stop crew time',
  `r_avg_4_pitstop_driver_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average 4-wheel pit stop driver time',
  `r_total_4_pitstops` int(10) unsigned DEFAULT NULL COMMENT 'Race total 4-wheel pit stops',
  `r_avg_2l_pitstop_crew_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average 2-left tire pit stop crew time',
  `r_avg_2l_pitstop_driver_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average 2-left tire pit stop driver time',
  `r_total_2l_pitstops` int(10) unsigned DEFAULT NULL COMMENT 'Race total 2-left tire pit stops',
  `r_avg_2r_pitstop_crew_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average 2-right tire pit stop crew time',
  `r_avg_2r_pitstop_driver_time` decimal(14,3) DEFAULT NULL COMMENT 'Race average 2-right tire pit stop driver time',
  `r_total_2r_pitstops` int(10) unsigned DEFAULT NULL COMMENT 'Race total 2-right tire pit stops',
  `r_total_penalties` int(10) unsigned DEFAULT NULL COMMENT 'Race total penalties',
  `r_total_race_laps` int(10) unsigned DEFAULT NULL COMMENT 'Race total race laps',
  `r_total_race_miles` decimal(16,3) DEFAULT NULL COMMENT 'Race total race miles',
  `q_finish_position` int(10) unsigned DEFAULT NULL COMMENT 'Qualifying finish position',
  `q_best_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Qualifying best speed',
  `q_best_time` time(3) DEFAULT NULL COMMENT 'Qualifying best time',
  `pt_min_finish_position` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions minimum finish position',
  `pt_max_finish_position` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions maximum finish position',
  `pt_avg_finish_position` decimal(12,3) DEFAULT NULL COMMENT 'All practice sessions average finish position',
  `pt_min_best_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'All practice sessions minimum best speed',
  `pt_max_best_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'All practice sessions maximum best speed',
  `pt_avg_best_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'All practice sessions average best speed',
  `pt_min_best_time` time(3) DEFAULT NULL COMMENT 'All practice sessions minimum best time',
  `pt_max_best_time` time(3) DEFAULT NULL COMMENT 'All practice sessions maximum best time',
  `pt_avg_best_time` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average best time',
  `pt_min_total_laps` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions minimum total laps',
  `pt_max_total_laps` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions maximum total laps',
  `pt_avg_total_laps` decimal(12,3) DEFAULT NULL COMMENT 'All practice sessions average total laps',
  `pt_sum_total_laps` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions sum total laps',
  `pt_min_5_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions minimum 5-lap average time',
  `pt_max_5_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions maximum 5-lap average time',
  `pt_avg_5_lap_average_time` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average 5-lap average time',
  `pt_min_10_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions minimum 10-lap average time',
  `pt_max_10_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions maximum 10-lap average time',
  `pt_avg_10_lap_average_time` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average 10-lap average time',
  `pt_min_20_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions minimum 20-lap average time',
  `pt_max_20_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions maximum 20-lap average time',
  `pt_avg_20_lap_average_time` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average 20-lap average time',
  `pt_min_25_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions minimum 25-lap average time',
  `pt_max_25_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions maximum 25-lap average time',
  `pt_avg_25_lap_average_time` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average 25-lap average time',
  `pt_min_30_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions minimum 30-lap average time',
  `pt_max_30_lap_average_time` time(3) DEFAULT NULL COMMENT 'All practice sessions maximum 30-lap average time',
  `pt_avg_30_lap_average_time` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average 30-lap average time',
  `pt_min_10_lap_average_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'All practice sessions minimum 10-lap average speed',
  `pt_max_10_lap_average_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'All practice sessions maximum 10-lap average speed',
  `pt_avg_10_lap_average_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'All practice sessions average 10-lap average speed',
  `pt_min_10_lap_start` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions minimum 10-lap start',
  `pt_max_10_lap_start` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions maximum 10-lap start',
  `pt_avg_10_lap_start` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average 10-lap start',
  `pt_min_10_lap_end` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions minimum 10-lap end',
  `pt_max_10_lap_end` int(10) unsigned DEFAULT NULL COMMENT 'All practice sessions maximum 10-lap end',
  `pt_avg_10_lap_end` decimal(14,3) DEFAULT NULL COMMENT 'All practice sessions average 10-lap end',
  `pf_finish_position` int(10) unsigned DEFAULT NULL COMMENT 'Last practice session finish position',
  `pf_best_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Last practice session best speed',
  `pf_best_time` time(3) DEFAULT NULL COMMENT 'Last practice session best time',
  `pf_total_laps` int(10) unsigned DEFAULT NULL COMMENT 'Last practice session total laps',
  `pf_5_lap_average_time` time(3) DEFAULT NULL COMMENT 'Last practice session 5-lap average time',
  `pf_10_lap_average_time` time(3) DEFAULT NULL COMMENT 'Last practice session 10-lap average time',
  `pf_20_lap_average_time` time(3) DEFAULT NULL COMMENT 'Last practice session 20-lap average time',
  `pf_25_lap_average_time` time(3) DEFAULT NULL COMMENT 'Last practice session 25-lap average time',
  `pf_30_lap_average_time` time(3) DEFAULT NULL COMMENT 'Last practice session 30-lap average time',
  `pf_10_lap_average_speed` decimal(8,3) unsigned DEFAULT NULL COMMENT 'Last practice session 10-lap average speed',
  `pf_10_lap_start` int(10) unsigned DEFAULT NULL COMMENT 'Last practice session 10-lap start',
  `pf_10_lap_end` int(10) unsigned DEFAULT NULL COMMENT 'Last practice session 10-lap end',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT 'Creation timestamp.',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Last update timestamp.',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT 'Soft-delete timestamp; NULL means active.',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci COMMENT='Weekly enriched feature/output table consumed by modeling and reporting. Race week for car/driver/manufacturer/team/season.';
